    "x": "以下は、「がんのリハビリテーション診療ガイドライン 第2版」（日本リハビリテーション医学会、2019年）の記載にもとづきます。推奨の強さは、1（強く推奨する）、2（提案する）、エビデンスの確実性は、A（強）、B（中）、C（弱）、D（とても弱）で示されます。がんの種類・進行度・治療内容、骨転移や血球減少などの合併症によって、個別の適応と運動の負荷量は大きく異なるため、主治医・多職種チームと連携してください。"
