    "x": "点数や基準は改定ごとに変わります。この記事は、厚生労働省「令和8年度診療報酬改定 4.包括期・慢性期入院医療」の内容にもとづきます。実際の算定は、最新の告示・通知と所属施設の届出内容で確認してください。確認日：2026年10月23日。"
